const input = $input.first().json.body ?? {};
const { inn, ogrn, scenario, observed_at } = input;
const date = typeof observed_at === 'string' ? Date.parse(observed_at) : NaN;
const ip = typeof inn === 'string' && inn.length === 12;
const innWeights = ip
  ? [[7,2,4,10,3,5,9,4,6,8],[3,7,2,4,10,3,5,9,4,6,8]]
  : [[2,4,10,3,5,9,4,6,8]];
const validInn = typeof inn === 'string' && /^(?:[0-9]{10}|[0-9]{12})$/.test(inn)
  && innWeights.every(weights => weights.reduce(
    (sum, weight, index) => sum + weight * Number(inn[index]), 0
  ) % 11 % 10 === Number(inn[weights.length]));
const validOgrn = typeof ogrn === 'string' && (ip ? /^[0-9]{15}$/ : /^[0-9]{13}$/).test(ogrn)
  && Number(BigInt(ogrn.slice(0, -1)) % (ip ? 13n : 11n) % 10n) === Number(ogrn.slice(-1));
if (!validInn || !validOgrn || !Number.isFinite(date)
    || !['green','arbitration','bankruptcy','timeout'].includes(scenario)) {
  return [{json:{statusCode:422,body:{detail:'Invalid mock registry input'}}}];
}
const timeout = scenario === 'timeout';
const young = scenario === 'arbitration';
const stop = scenario === 'bankruptcy';
const [fns, kad, enforcement] = await Promise.all([
  Promise.resolve().then(() => ({
    legal_entity_status: timeout ? null : 'ACTIVE',
    registration_age_months: timeout ? null : young ? 8 : 48,
    charter_capital_rub: timeout || ip ? null : '10000.00',
    fns_address_unreliable: timeout ? null : stop,
  })),
  Promise.resolve().then(() => ({
    defendant_claims_rub: timeout ? null : young ? '600000.00' : '0.00',
  })),
  Promise.resolve().then(() => ({
    tax_debt_rub: timeout ? null : '0.00', bankruptcy: timeout ? null : stop,
  })),
]);
return [{json:{statusCode:200,body:{inn,ogrn,...fns,...kad,...enforcement,
  observed_at:new Date(date).toISOString()}}}];
